{"description":"Test SSH connection via port 2222 with password","cmd":"expect -c '
set timeout 20
log_user 1
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PubkeyAuthentication=no root@localhost
expect {
  -re "password:" { send "password123\r" }
  timeout { puts "TIMEOUT waiting for password prompt"; exit 1 }
}
expect {
  -re "#" { send "echo SSH_OK_MARKER\r" }
  timeout { puts "TIMEOUT waiting for shell prompt"; exit 1 }
}
expect {
  -re "SSH_OK_MARKER" { puts "\nSSH_TEST_PASSED" }
  timeout { puts "TIMEOUT waiting for command output" }
}
send "exit\r"
expect eof
'","yield_time_ms":30000}

